const f=$input.first().json,name=String(f.name||'');
const m=name.match(/^TICKET[-_ ]?(\d+)(?:_after)?\.(pdf|jpg|jpeg|png|webp|heic)$/i);
const ext=(name.match(/\.([a-z0-9]+)$/i)||[])[1]?.toLowerCase();
const isReport=ext==='pdf',isPhoto=['jpg','jpeg','png','webp','heic'].includes(ext);
if(!isReport&&!isPhoto)return [];
return [{json:{matched:!!m,ticket_id:m?Number(m[1]):null,upload_kind:isReport?'REPORT':'PHOTO',
report_file_id:isReport?f.id:null,report_file_name:isReport?name:null,report_link:isReport?(f.webViewLink||''):'',
photo_file_id:isPhoto?f.id:null}}];

// Rename the BEFORE photo binary so it can be merged with the AFTER photo
// (which keeps the default 'data' key) without a key collision.
const item = $input.first();
return [{ json: item.json, binary: { before_photo: (item.binary || {}).data } }];

// Parse Claude's before/after verdict and assemble the closure payload.
const raw = ($input.first().json.text || '').trim()
  .replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let v;
try {
  v = JSON.parse(raw);
} catch (e) {
  v = { repair_verified: null, confidence: 0,
        observations: 'Could not parse AI verdict. Raw output: ' + raw.slice(0, 200) };
}

const ticket = $('Fetch Ticket').first().json;
const x = $('Find AFTER Photo').first().json;
const sql = (s) => String(s ?? '').replace(/'/g, "''");

return [{
  json: {
    ...ticket,
    after_file_id: x.id,
    after_link: x.webViewLink || '',
    repair_verified: v.repair_verified === true,
    ai_confidence: v.confidence ?? 0,
    observations: v.observations || '',
    verification_sql: sql(JSON.stringify(v)),
  },
}];

// Deployment adaptation for n8n 2.29.9: parse report PDFs in the Python API.
// Retain the release's field names and evidence-quality decisions.
const buf = await this.helpers.getBinaryDataBuffer(0, 'data');
const x = $('Extract Ticket ID').first().json;
let text = '', pages = 0, parseError = null;
try {
  if (buf.length > 20 * 1024 * 1024) throw new Error('Report exceeds 20 MiB');
  const base = String($env.IFC_SERVICE_URL || '').replace(/\/+$/, '');
  if (!base) throw new Error('Configure IFC_SERVICE_URL');
  const parsed = await this.helpers.httpRequest({
    method: 'POST', url: base + '/reports/extract', json: true,
    body: {pdfB64: buf.toString('base64')}, timeout: 60000,
  });
  if (typeof parsed.text !== 'string' || !Number.isInteger(parsed.numpages)) {
    throw new Error('Invalid report extraction response');
  }
  text = parsed.text.replace(/\r\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
  pages = parsed.numpages;
} catch (e) {
  parseError = String(e?.response?.body?.detail || e?.message || e).slice(0, 1000);
}
const words = text ? text.split(/\s+/).filter(Boolean).length : 0;
const quality = parseError ? 'PARSE_ERROR' : (words < 5 ? 'EMPTY' : 'OK');
return [{json:{...x, report_text:text, report_words:words, report_pages:pages,
  report_quality:quality, report_parse_error:parseError}}];

// Assemble everything the completion assessment needs, from whichever branch ran.
//
// The vision nodes execute only when a photograph accompanied the report, so the
// vision verdict is looked up defensively: referencing a node that did not run in
// this execution throws, and that throw is the normal no-photo case.
const report = $('Extract Report Text').first().json;
const ticket = $('Fetch Ticket').first().json;

let vision = null;
let after = {}; try { after = $('Find AFTER Photo').first().json; } catch {}
try {
  const v = $('Parse Verification').first().json;
  vision = {
    repair_verified: v.repair_verified,
    confidence: v.ai_confidence,
    observations: v.observations,
    after_file_id: v.after_file_id,
    after_link: v.after_link,
  };
} catch (e) {
  vision = null;   // no photograph was supplied - the report stands alone
}

return [{
  json: {
    ticket_id: ticket.id,
    object_type: ticket.object_type || ticket.ifc_name || 'unspecified object',
    damage_description: ticket.damage_description || ticket.description || '',
    technician_name: ticket.technician_name || '',
    technician_email: ticket.technician_email || '',
    report_text: report.report_text,
    report_quality: report.report_quality,
    report_words: report.report_words,
    report_file_id: report.report_file_id,
    report_link: report.report_link,
    photo_supplied: !!after.id,
    after_file_id: after.id || null, after_link: after.webViewLink || "",
    vision,
    vision_summary: vision
      ? `A photograph was supplied. Image comparison verdict: repair_verified=${vision.repair_verified}, confidence=${vision.confidence}. ${vision.observations || ''}`
      : 'No photograph was supplied. Judge the completion from the written report alone.',
  },
}];

parameters.text:
=You are the completion-assessment engine of a facility-maintenance system. Decide whether a technician's written report credibly shows the work is finished.

TICKET {{ $json.ticket_id }} - object: {{ $json.object_type }}
Originally reported issue: {{ $json.damage_description }}
Technician: {{ $json.technician_name }}

TECHNICIAN'S REPORT (extraction quality: {{ $json.report_quality }}, {{ $json.report_words }} words):
---
{{ $json.report_text }}
---

PHOTOGRAPHIC EVIDENCE: {{ $json.vision_summary }}

The photograph is optional; the report is the evidence of record. Judge the report on whether it describes what was actually done to resolve the reported issue. A report that is empty, unreadable, generic, or describes work unrelated to the reported issue is not a completion.

Respond with ONLY a minified JSON object, no markdown fences:
{"work_complete": true or false, "confidence": number between 0 and 1, "recommended_status": one of "PENDING_APPROVAL" or "REWORK" or "NEEDS_TRIAGE", "summary": one short factual sentence for the facility manager, "concerns": short string, empty if none}

Use PENDING_APPROVAL when the report credibly describes the completed repair. Use REWORK when the work appears incomplete, unrelated, or the report is unusable. Use NEEDS_TRIAGE only when the report indicates the original diagnosis was wrong.

parameters.jsCode:
// Validate the chain's verdict and decide the ticket status.
//
// The model proposes a status; this node decides it. An unparseable response or a
// status outside the allowed vocabulary becomes REWORK with an explicit reason -
// never a silent PENDING_APPROVAL, and never an invented status reaching SQL.
const ALLOWED = ["PENDING_APPROVAL", "REWORK", "NEEDS_TRIAGE"];

const raw = ($input.first().json.text || '').trim()
  .replace(/^```(json)?/i, '').replace(/```$/, '').trim();

let v;
let parseError = null;
try {
  v = JSON.parse(raw);
} catch (e) {
  parseError = 'Could not parse the assessment. Raw output: ' + raw.slice(0, 200);
  v = {};
}

const input = $('Build Assessment Input').first().json;
const ticket = $('Fetch Ticket').first().json;

let status = String(v.recommended_status || '').toUpperCase();
let statusReason = null;
if (!ALLOWED.includes(status)) {
  statusReason = parseError || ('Model proposed an unrecognised status: ' + (v.recommended_status ?? 'none'));
  status = 'REWORK';
}
// A report we could not read is never a completion, whatever the model concluded.
if (input.report_quality !== 'OK' && status === 'PENDING_APPROVAL') {
  status = 'REWORK';
  statusReason = 'Report text could not be read (' + input.report_quality + ').';
}

// When the node overrides the model, the override reason leads: the facility
// manager must not read a confident model summary next to a status that
// contradicts it and have no idea why.
const summary = statusReason
  ? statusReason + (v.summary ? ' (model reported: ' + v.summary + ')' : '')
  : (v.summary || '');

const verification = {
  source: 'REPORT',
  photo_supplied: input.photo_supplied,
  work_complete: v.work_complete === true,
  confidence: typeof v.confidence === 'number' ? v.confidence : 0,
  summary,
  model_summary: v.summary || '',
  status_overridden: statusReason !== null,
  concerns: v.concerns || '',
  report_quality: input.report_quality,
  report_words: input.report_words,
  vision: input.vision,
  status_reason: statusReason,
};

const sql = (s) => String(s ?? '').replace(/'/g, "''");

return [{
  json: {
    ...ticket,
    ticket_id: input.ticket_id,
    id: input.ticket_id,
    resolved_status: status,
    work_complete: verification.work_complete,
    ai_confidence: verification.confidence,
    observations: verification.summary,
    concerns: verification.concerns,
    photo_supplied: input.photo_supplied,
    report_text: input.report_text,
    report_file_id: input.report_file_id,
    report_link: input.report_link,
    after_file_id: input.after_file_id || (input.vision && input.vision.after_file_id) || null,
    after_link: input.after_link || (input.vision && input.vision.after_link) || '',
    technician_name: input.technician_name,
    technician_email: input.technician_email,
    object_type: input.object_type,
    damage_description: input.damage_description,
    verification_sql: sql(JSON.stringify(verification)),
    report_text_sql: sql(input.report_text || ''),
  },
}];

const raw=$input.first().json;
const decision=typeof raw.data?.approved==='boolean'?(raw.data.approved?'APPROVED':'REJECTED'):'EXPIRED';
const a=$('Parse Completion Assessment').first().json;
const receipt=$('Set Pending Approval').first().json;
return [{json:{ticketId:a.id,approvalId:receipt.approval_id,operationKey:'wf2:'+a.id+':'+receipt.approval_id,
decision,attemptBudget:3,ifcGlobalId:a.ifc_global_id||null,
ifcServiceUrl:$env.IFC_SERVICE_URL,technicianId:a.technician_id??null,technicianName:a.technician_name||'',
technicianEmail:a.technician_email||'',objectType:a.object_type||'',damageDescription:a.damage_description||'',
fmEmail:'fm@test.invalid',observations:a.observations||'',reportLink:a.report_link||'',afterLink:a.after_link||'',photoSupplied:a.photo_supplied===true,
rejectionReason:decision==='REJECTED'?'The facility manager explicitly rejected this completion. No detailed reason was supplied.':null,
objectives:decision==='APPROVED'?['log_ifc_maintenance','close_ticket','update_technician_stats','notify_technician_closed','notify_fm_closed']:
decision==='REJECTED'?['reopen_for_rework','notify_technician_rework']:[]}}];

// Normalise the chat turn, and fix the date anchors once.
//
// The agent must not work out what "this week" or "a month" means for itself:
// the chat and the weekly report have to agree, and a model that computes dates
// from a system prompt will not agree with SQL that computes them from now().
// Everything time-relative is decided here and handed over as an ISO string.
const t = $input.first().json;

const raw = String(t.chatInput != null ? t.chatInput : (t.question || ''))
  .replace(/\s+/g, ' ')
  .trim();
const question = raw.slice(0, 1500);
const sessionId = String(t.sessionId || t.sessionid || 'fm-default').slice(0, 120);

const now = new Date();
const iso = (d) => d.toISOString();
const back = (days) => iso(new Date(now.getTime() - days * 86400000));

return [{
  json: {
    sessionId,
    question,
    asked: question.length > 0,
    truncated: raw.length > 1500,
    now: iso(now),
    today: new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Rome',year:'numeric',month:'2-digit',day:'2-digit'}).format(now),
    timezone: 'Europe/Rome',
    week_start: back(7),
    month_start: back(30),
    stale_days: 30,
  },
}];

// An empty turn should not cost a model call.
return [{
  json: {
    output: [
      'Ask me anything about the maintenance tickets. For example:',
      '',
      '- what is the status of ticket 42?',
      '- which tickets are still open after a month?',
      '- how many tickets did we close last week?',
      '- what is Mario Rossi working on?',
      '- show me everything ever raised on the second-floor radiators',
    ].join('\n'),
  },
}];

// The chat trigger returns whatever the last node emits, so the answer is
// shaped here rather than left to depend on the logging node's output.
//
// The agent runs with continueRegularOutput: a tool failure it could not recover
// from produces no `output` rather than an error page in the chat window. Say so
// plainly instead of returning an empty bubble.
const ctx = $('FM Chat Context').first().json;

let answer = '';
try {
  answer = String($('FM Dashboard Agent').first().json.output || '').trim();
} catch (e) {
  answer = '';
}

if (!answer) {
  answer = 'I could not complete that lookup. The database or the model did not '
    + 'answer. Nothing was changed - this dashboard only reads. Please try again, '
    + 'or ask a narrower question.';
}

if (ctx.truncated) {
  answer += '\n\n_(Your question was longer than 1500 characters; only the first '
    + '1500 were used.)_';
}

return [{ json: { output: answer, sessionId: ctx.sessionId } }];

// The reporting window: the seven days ending at the moment the schedule fires.
//
// Fixed rather than derived from the previous run, so a report can be re-run by
// hand and produce the same figures. The window is recorded with the report, so
// a skipped week is visible in ticket_events rather than silently absorbed.
const now = new Date();
const start = new Date(now.getTime() - 7 * 86400000);
const iso = (d) => d.toISOString();
const day = (d) => new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',dateStyle:'medium',timeStyle:'short'}).format(d);

return [{
  json: {
    periodStart: iso(start),
    periodEnd: iso(now),
    periodLabel: day(start) + ' to ' + day(now) + ' (Europe/Rome)',
    staleDays: 30,
    generatedAt: iso(now),
  },
}];

// Turn the single JSON document the query returned into the report.
//
// Every figure here was computed by SQL. Nothing in this node counts anything:
// it groups, sorts and formats, so the numbers in the email are the numbers in
// the database and the model that writes the covering paragraph later cannot
// change them.
const r = $input.first().json.report || {};
const w = $('Report Window').first().json;

const totals = r.totals || {};
const byStatus = r.by_status || [];
const changes = r.changes || [];
const stale = r.stale || [];
const staleDays = r.stale_days || 30;

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const day = (s) => (s ? new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',dateStyle:'medium'}).format(new Date(s)) : '');

// --- status changes, grouped into one row per ticket ----------------------
// A ticket that moved RECEIVED -> ASSIGNED -> WORK_DONE in one week is one line
// showing the path, not three lines the manager has to reassemble.
const byTicket = new Map();
for (const c of changes) {
  const key = c.ticket_id;
  if (!byTicket.has(key)) {
    byTicket.set(key, {
      ticket_id: key,
      description: c.description || '',
      ifc_name: c.ifc_name || '',
      ifc_storey: c.ifc_storey || '',
      technician_name: c.technician_name || '',
      current_status: c.current_status || '',
      age_days: c.age_days,
      first_from: c.status_from,
      steps: [],
      last_at: c.changed_at,
    });
  }
  const row = byTicket.get(key);
  row.steps.push(c.status_to);
  row.current_status = c.current_status || row.current_status;
  row.last_at = c.changed_at;
}

const movedTickets = Array.from(byTicket.values())
  .sort((a, b) => String(b.last_at).localeCompare(String(a.last_at)));

for (const m of movedTickets) {
  m.path = [m.first_from == null ? 'NEW' : m.first_from].concat(m.steps).join(' -> ');
  m.closed_this_week = m.steps.includes('CLOSED');
  m.still_open = !['CLOSED', 'DUPLICATE', 'REJECTED'].includes(m.current_status);
  // A ticket that moved this week but is already past the stale threshold is
  // still overdue: movement is not progress.
  m.overdue = m.still_open && Number(m.age_days) >= staleDays;
}

const staleIds = new Set(stale.map((s) => s.id));
const movedIds = new Set(movedTickets.map((m) => m.ticket_id));
// Overdue and untouched all week: the worst category, listed first.
for (const s of stale) {
  s.moved_this_week = movedIds.has(s.id);
}
const stalled = stale.filter((s) => !s.moved_this_week);

const subject = '[CBM] Weekly maintenance report ' + w.periodLabel
  + ' - ' + movedTickets.length + ' updated, ' + stale.length + ' over '
  + staleDays + ' days';

// --- tables ---------------------------------------------------------------
const th = 'style="text-align:left;padding:6px 10px;border-bottom:2px solid #444;font-size:13px"';
const td = 'style="padding:6px 10px;border-bottom:1px solid #ddd;font-size:13px"';
const tdWarn = 'style="padding:6px 10px;border-bottom:1px solid #ddd;font-size:13px;color:#b00020;font-weight:bold"';

// `rows` is already rendered HTML, not an array: each caller builds its own
// row shape and this only wraps them.
const table = (headers, rows) => !rows ? '' :
  '<table style="border-collapse:collapse;width:100%;margin:8px 0 18px 0">'
  + '<tr>' + headers.map((h) => '<th ' + th + '>' + esc(h) + '</th>').join('') + '</tr>'
  + rows + '</table>';

const statusRows = byStatus.map((s) =>
  '<tr><td ' + td + '>' + esc(s.status) + '</td><td ' + td + '>' + s.tickets + '</td></tr>').join('');

const changeRows = movedTickets.map((m) =>
  '<tr>'
  + '<td ' + td + '>#' + m.ticket_id + '</td>'
  + '<td ' + td + '>' + esc(m.path) + '</td>'
  + '<td ' + (m.overdue ? tdWarn : td) + '>' + esc(m.current_status)
  + (m.overdue ? ' (' + m.age_days + 'd old)' : '') + '</td>'
  + '<td ' + td + '>' + esc(m.ifc_name || m.description.slice(0, 60)) + '</td>'
  + '<td ' + td + '>' + esc(m.technician_name || 'unassigned') + '</td>'
  + '</tr>').join('');

const staleRows = stale.map((s) =>
  '<tr>'
  + '<td ' + td + '>#' + s.id + '</td>'
  + '<td ' + tdWarn + '>' + s.age_days + ' days</td>'
  + '<td ' + td + '>' + esc(s.status) + '</td>'
  + '<td ' + td + '>' + (s.moved_this_week ? 'moved this week'
      : 'no change for ' + s.days_since_last_change + ' days') + '</td>'
  + '<td ' + td + '>' + esc(s.ifc_name || s.description.slice(0, 60)) + '</td>'
  + '<td ' + td + '>' + esc(s.technician_name || 'unassigned') + '</td>'
  + '</tr>').join('');

const sections = [];
sections.push('<h2 style="font-size:16px;margin:22px 0 4px 0">Where everything stands</h2>'
  + '<p style="font-size:13px;margin:0 0 6px 0">'
  + '<b>' + (totals.opened_in_window || 0) + '</b> raised and '
  + '<b>' + (totals.closed_in_window || 0) + '</b> closed this week. '
  + '<b>' + (totals.open_now || 0) + '</b> open now, of '
  + '<b>' + (totals.tickets_all_time || 0) + '</b> ever raised.</p>'
  + table(['Status', 'Tickets'], statusRows));

sections.push('<h2 style="font-size:16px;margin:22px 0 4px 0">Changed status this week ('
  + movedTickets.length + ')</h2>'
  + (movedTickets.length
     ? table(['Ticket', 'Path', 'Now', 'Element', 'Technician'], changeRows)
     : '<p style="font-size:13px">No ticket changed status during this period.</p>'));

sections.push('<h2 style="font-size:16px;margin:22px 0 4px 0;color:#b00020">'
  + 'Open longer than ' + staleDays + ' days (' + stale.length + ')</h2>'
  + (stale.length
     ? '<p style="font-size:13px;margin:0 0 6px 0">' + stalled.length
       + ' of these did not move at all this week.</p>'
       + table(['Ticket', 'Age', 'Status', 'Last change', 'Element', 'Technician'], staleRows)
     : '<p style="font-size:13px">Nothing has been outstanding for more than '
       + staleDays + ' days.</p>'));

const body = sections.join('');

// --- what the model is allowed to see -------------------------------------
// Figures only, already computed. The paragraph it writes is a covering note on
// these numbers; it is given nothing it could use to invent a different set.
const facts = {
  period: w.periodLabel,
  period_start: w.periodStart,
  period_end: w.periodEnd,
  stale_days: staleDays,
  opened_in_window: totals.opened_in_window || 0,
  closed_in_window: totals.closed_in_window || 0,
  open_now: totals.open_now || 0,
  tickets_all_time: totals.tickets_all_time || 0,
  tickets_changed_status: movedTickets.length,
  tickets_closed_this_week: movedTickets.filter((m) => m.closed_this_week).length,
  overdue_total: stale.length,
  overdue_untouched_this_week: stalled.length,
  oldest_overdue_days: stale.length ? Math.max.apply(null, stale.map((s) => Number(s.age_days) || 0)) : 0,
  by_status: byStatus,
  overdue_tickets: stale.slice(0, 10).map((s) => ({
    id: s.id, status: s.status, age_days: s.age_days,
    technician: s.technician_name || 'unassigned',
    element: s.ifc_name || '', moved_this_week: s.moved_this_week,
  })),
};

const narrative_prompt = [
  'You are writing the opening paragraph of a facility maintenance report for the',
  'facility manager. The figures below are already final and were computed from the',
  'database. Write three or four sentences of plain prose.',
  '',
  'Rules:',
  '- Use only the figures given. Do not introduce any number that is not below.',
  '- Say what changed this week, then what needs the manager\'s attention.',
  '- Name at most three specific ticket numbers, chosen from overdue_tickets.',
  '- No greeting, no sign-off, no bullet points, no headings, no markdown.',
  '- If nothing moved and nothing is overdue, say so in one sentence.',
  '',
  'FIGURES:',
  JSON.stringify(facts, null, 2),
].join('\n');

return [{
  json: {
    subject,
    body_html: body,
    period_label: w.periodLabel,
    generated_at: w.generatedAt,
    changed_count: movedTickets.length,
    stale_count: stale.length,
    stalled_count: stalled.length,
    stale_days: staleDays,
    facts,
    narrative_prompt,
  },
}];

// Assemble the email. The narrative chain runs with continueRegularOutput, so a
// model outage costs the opening paragraph and nothing else: the tables below it
// are already built and the report still goes out on time.
const b = $('Build Weekly Report').first().json;

let narrative = '';
try {
  narrative = String($input.first().json.text || '').trim();
} catch (e) {
  narrative = '';
}

// A model that ignored the instructions and emitted JSON or a heading is not
// worth printing above the manager's figures.
if (narrative.startsWith('{') || narrative.startsWith('#') || narrative.length > 1200) {
  narrative = '';
}

const esc = (s) => String(s == null ? '' : s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const opening = narrative
  ? '<p style="font-size:14px;line-height:1.5">' + esc(narrative) + '</p>'
  : '<p style="font-size:13px;color:#666"><i>The written summary could not be '
    + 'generated for this run; the figures below are complete.</i></p>';

const html = '<div style="font-family:-apple-system,Segoe UI,Roboto,sans-serif;'
  + 'max-width:820px;color:#222">'
  + '<h1 style="font-size:19px;margin:0 0 2px 0">Weekly maintenance report</h1>'
  + '<p style="font-size:12px;color:#666;margin:0 0 14px 0">' + esc(b.period_label)
  + ' &middot; generated ' + esc(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',dateStyle:'medium',timeStyle:'short'}).format(new Date(b.generated_at)))
  + ' (Europe/Rome)</p>'
  + opening
  + b.body_html
  + '<p style="font-size:11px;color:#888;border-top:1px solid #ddd;padding-top:8px">'
  + 'Status changes are read from the CBM_STATUS_CHANGED audit trail. '
  + 'Ask the dashboard chat for anything not shown here - it can see the full '
  + 'ticket history.</p>'
  + '</div>';

return [{
  json: {
    subject: b.subject,
    html,
    narrative_used: narrative.length > 0,
    record: {
      period_start: b.facts.period_start,
      period_end: b.facts.period_end,
      changed: b.changed_count,
      overdue: b.stale_count,
      overdue_untouched: b.stalled_count,
      opened: b.facts.opened_in_window,
